  const seed=await page();scope(seed,'task:category-objectnav');await loaded(seed);await frames(seed.w);const relation=change(seed,90);relation.open=true;const target=relation.querySelector('[data-change-target="pos:l:98bc421b8bfd17d6699922"]'),targetId=target.id;target.focus();seed.w.dispatchEvent(new seed.w.Event('pagehide'));const saved=JSON.parse(JSON.stringify(seed.w.history.state)),hash=seed.w.location.hash;assert.equal(seed.w.NavigationProductModel.getBucket(seed.w.NavigationProductApp.getState()).focusTarget,targetId);await closePage(seed);
  const pending=new Map(),x=await page({saved,hash,holdFrames:mode.startsWith('pre-'),width:mode==='reader'?1440:undefined,fetch:url=>new Promise(resolve=>pending.set(url,resolve))});t.after(()=>x.w.close());assert.equal(x.doc.getElementById(targetId),null);const fallback=x.doc.activeElement;
  if(mode==='pre-focus')x.doc.querySelector('#np-tree [role=treeitem]').focus();
  if(mode==='pre-key')x.doc.body.dispatchEvent(new x.w.KeyboardEvent('keydown',{key:'Escape',bubbles:true}));
  if(mode==='focus'){x.doc.getElementById('np-node-search').focus();fallback.focus();}
  if(mode==='key')fallback.dispatchEvent(new x.w.KeyboardEvent('keydown',{key:'Shift',bubbles:true}));
  if(mode==='pointer')fallback.dispatchEvent(new x.w.MouseEvent('mousedown',{bubbles:true}));
  if(mode==='click')fallback.dispatchEvent(new x.w.MouseEvent('click',{bubbles:true}));
  if(mode==='wheel')fallback.dispatchEvent(new x.w.WheelEvent('wheel',{deltaY:20,bubbles:true}));
  if(mode==='touch')fallback.dispatchEvent(new x.w.Event('touchstart',{bubbles:true}));
  if(mode==='scope')scope(x,'task:aerial-visual-object-search');
  if(mode==='reader'){x.w.NavigationProductApp.navigate(x.w.NavigationProductModel.routeForPosition(x.w.NavigationProductApp.getBundle(),x.w.NavigationProductApp.getState().route,'pos:l:98bc421b8bfd17d6699922'));await frames(x.w);const toggle=x.doc.getElementById('np-reader-toggle');assert.equal(toggle.hidden,false);toggle.click();toggle.click();}
  if(mode.startsWith('pre-')){const chosen=x.doc.activeElement;x.flushFrames();assert.equal(x.doc.activeElement,chosen,'initial delayed frame must not steal newer focus');}else await frames(x.w);const expectedFocus=x.doc.activeElement;const beforeRoute=JSON.stringify(x.w.NavigationProductApp.getState().route);x.doc.getElementById('np-detail-scroll').scrollTop=93;
  for(const url of [...pending.keys()])release(pending,url);await loaded(x);await wait(50);const restored=x.doc.getElementById(targetId);
  if(mode==='restore'){assert.ok(restored);assert.equal(x.doc.activeElement,restored);for(let at=restored.parentElement;at;at=at.parentElement)if(at.tagName==='DETAILS')assert.equal(at.open,true);}
  else{assert.equal(x.doc.activeElement,expectedFocus);if(restored)assert.equal(restored.closest('details').open,false);}
  assert.equal(JSON.stringify(x.w.NavigationProductApp.getState().route),beforeRoute);assert.equal(x.doc.getElementById('np-detail-scroll').scrollTop,mode==='restore'?saved[x.w.NavigationProductModel.KEY].contexts[x.w.NavigationProductModel.contextKey(x.w.NavigationProductApp.getState().route)].detailScrollByTree.l:93);assert.deepEqual(x.errors,[]);
